entries[53385] = { ["name"] = "Divine Storm", ["text"] = "3 Holy Power\nInstant cast\nRequires Melee Weapon\nAn area attack that consumes 3 charges of Holy Power to cause 100% weapon damage as Holy damage to all enemies within 8 yards. [ Glyph of Divine Storm : Using Divine Storm will also heal you for 5% of your maximum health ]" }
